  'Un restaurante que fluye,': { en: 'A restaurant that flows,', fr: 'Un restaurant fluide,', de: 'Ein Restaurant im Fluss,', 'es-ES': 'Un restaurante que fluye,', 'zh-CN': '让餐厅运转顺畅，' },
  'mesa a mesa.': { en: 'table by table.', fr: 'table par table.', de: 'Tisch für Tisch.', 'es-ES': 'mesa a mesa.', 'zh-CN': '一桌接一桌。' },
  'Coordina sala, pedidos y menú desde un solo lugar. Menos vueltas entre el salón y la cocina; más atención para tus clientes.': { en: 'Coordinate tables, orders, and menu in one place. Less running between dining room and kitchen; more attention for guests.', fr: 'Coordonnez tables, commandes et menu depuis un seul endroit. Moins d’allers-retours entre salle et cuisine, plus d’attention pour vos clients.', de: 'Koordinieren Sie Tische, Bestellungen und Menü an einem Ort. Weniger Wege zwischen Gastraum und Küche, mehr Aufmerksamkeit für Gäste.', 'es-ES': 'Coordina sala, pedidos y menú desde un solo lugar. Menos vueltas entre el salón y la cocina; más atención para tus clientes.', 'zh-CN': '在一个地方协调餐桌、订单和菜单。减少在餐厅与厨房之间奔走，把更多精力留给顾客。' },
  'Conoce Gestourant': { en: 'Discover Gestourant', fr: 'Découvrir Gestourant', de: 'Gestourant kennenlernen', 'es-ES': 'Conoce Gestourant', 'zh-CN': '了解 Gestourant' },
